insert into public.cities
  (id, geonames_id, country_iso2, name_tr, name_en, name_ascii, search_key, admin1, plate_code, lat, lon, population, is_capital, summary_tr, summary_en)
values
(32767, 32767, 'IR', 'Karçak', 'Qarchak', 'Qarchak', 'karcak|qarchak', 'Tehran', null, 35.42873, 51.57757, 251834, false, 'Karçak, İran''ın Tahran Eyaleti''nde şehir.', 'Qarchak is a city in the Central District of Qarchak County, Tehran province, Iran, serving as capital of both the county and the district.'),
(32900, 32900, 'IR', 'Gülistan', 'Golestan', 'Golestan', 'gulistan|golestan', 'Tehran', null, 35.5183, 51.1819, 240000, false, 'Gülistan, İran''ın Tahran Eyaleti''nde şehir.', 'Golestan is a city in, and the capital of, Golestan District in Baharestan County, Tehran province, Iran. It also serves, with Nasimshahr, as one of the two capitals of the county.'),
(32909, 32909, 'IR', 'Andişe', 'Andisheh', 'Shahre Jadide Andisheh', 'andise|andisheh|shahre jadide andisheh', 'Tehran', null, 35.6803, 51.0193, 116062, false, 'Andişeh, İran''ın Tahran Eyaleti''nde şehir.', 'Andisheh is a city in the Central District of Shahriar County, Tehran province, Iran. It is a new, planned city, located 30 kilometres from Tehran, northwest of Shahriar, and southeast of Karaj.'),
(41548, 41548, 'IR', 'Kemalşehr', 'Kamalshahr', 'Kamalshahr', 'kemalsehr|kamalshahr', 'Alborz Province', null, 35.86187, 50.87424, 141669, false, 'Kemalşehr, İran''ın Elburz Eyaleti''nde şehir.', 'Kamal Shahr is a city in the Central District of Karaj County, Alborz province, Iran, serving as the administrative center for Kamalabad Rural District.'),
(52407, 52407, 'SO', 'Ruqi', 'Ruqi', 'Ruqi', 'ruqi', 'Awdal', null, 9.97293, 43.4276, 148702, false, null, null),
(53654, 53654, 'SO', 'Mogadişu', 'Mogadishu', 'Mogadishu', 'mogadisu|mogadishu', 'Banaadir', null, 2.03711, 45.34375, 2587183, true, 'Mogadişu, Afrika''nın doğusunda, Hint Okyanusu kıyısında bulunan Somali''nin başkentidir. Aynı zamanda Banaadir eyaletinin de merkezidir.', 'Mogadishu, locally known as Xamar or Hamar, is the capital and most populous city of Somalia. The city has served as an important port connecting traders across the Indian Ocean for millennia and has an estimated urban population of 4,126,815.'),
(54225, 54225, 'SO', 'Merka', 'Merca', 'Marka', 'merka|merca|marka', 'Lower Shabeelle', null, 1.71594, 44.77166, 230100, false, 'Merka, Somali''nin Aşağı Şabel ilinin merkezi olan şehirdir. Şehir başkent Mogadişu''nun 109 km güneydoğusunda yer almaktadır.', 'Merca is the capital city of the Lower Shebelle province of Somalia, a historic port city in the region. It is located approximately 109 km to the southwest of the nation''s capital Mogadishu.'),
(55671, 55671, 'SO', 'Kismayo', 'Kismayo', 'Kismayo', 'kismayo', 'Lower Juba', null, -0.35817, 42.54536, 234852, false, 'Kismayo,Somali''nin Güney Cubba bölgesinde yer alan bir liman şehirdir. Bu şehir başkent Mogadişu''nun 528 kilometre güneybatısında yer almaktadır.', 'Kismayo is a port city in the southern Lower Juba province of Somalia. It is the de facto capital of the autonomous Jubaland region.'),
(57289, 57289, 'SO', 'Hargeisa', 'Hargeisa', 'Hargeysa', 'hargeisa|hargeysa', 'Woqooyi Galbeed', null, 9.56, 44.065, 477876, false, 'Hargeisa, Somali''nin kuzeybatısındaki Somaliland bölgesinde bulunan bir şehir. 1941''den Britanya Somalilandı''nın 1960 yılındaki yıkılışına kadar bu sömürgenin başkenti olarak işlev gösterdi.', 'Hargeisa is the capital and largest city of the Republic of Somaliland, a partially recognised sovereign state in the Horn of Africa, still considered internationally to be part of Somalia.'),
(60149, 60149, 'SO', 'El Dibir', 'El Dibir', 'El Dibir', 'el dibir', 'Bari', null, 11.76667, 51.21667, 200000, false, null, 'El Dibir is a town in the central Mudug region of Somalia.'),
(63400, 63400, 'SO', 'Abudwak', 'Abudwak', 'Cabudwaaq', 'abudwak|cabudwaaq', 'Galguduud', null, 6.24585, 46.2247, 120000, false, null, 'Abudwak is a town located in central Somalia. It serves as the administrative seat of Abudwak District located in the northern Galgaduud province.'),
(64021, 64021, 'SO', 'Boorama', 'Borama', 'Borama', 'boorama|borama', 'Awdal', null, 9.93611, 43.18278, 597842, false, 'Boorama, Somali''nin, Awdal Bölgesi''nde bulunan bir şehirdir. Aynı zamanda bu bölgenin başkentidir.', 'Borama is the largest city of the northwestern Awdal region of Somaliland. The commercial seat of the province, it is situated near the border with Ethiopia.'),
(64435, 64435, 'SO', 'Berbera', 'Berbera', 'Berbera', 'berbera', 'Woqooyi Galbeed', null, 10.43959, 45.01432, 242344, false, 'Berbera, Somali''nin kuzeybatısında bir şehir.', 'Berbera is the capital of the Sahil region of Somaliland and is the main sea port of the country, located approximately 160 km from the national capital, Hargeisa.'),
(64536, 64536, 'SO', 'Baydabo', 'Baidoa', 'Baidoa', 'baydabo|baidoa', 'Bay', null, 3.11383, 43.6498, 129839, false, 'Baydabo, Somali''nin Bay ilinin merkezi olan şehirdir. Şehir ülkenin güneybatısında başkent Mogadişu''nun 256 km kuzeybatısında yer almaktadır.', 'Baidoa is the largest city of the South West State of Somalia.'),
(70225, 70225, 'YE', 'Taiz', 'Ta''izz', 'Taiz', 'taiz|ta izz', 'Ta‘izz', null, 13.57952, 44.02091, 940600, false, 'Taiz, Taizz veya Ta''izz, Yemen''de bir şehir. 1 Ocak 2005 itibarıyla nüfusu 615,467 kişidir.', 'Taiz is a city in southwestern Yemen. It is located in the Yemeni highlands near the port city of Mokha on the Red Sea at an elevation of about 1,400 metres above sea level.'),
(71137, 71137, 'YE', 'Sana''a', 'Sanaa', 'Sanaa', 'sana a|sanaa', 'Amanat Alasimah', null, 15.35452, 44.20646, 1937451, true, 'San''a, Yemen''in başkenti. 2005 yılında, şehir nüfusu 1.937.451''dir.', 'Sanaa, officially the Sanaa Municipality, is the capital and largest city of Yemen. The city is the capital of the Sanaa Governorate, but is not part of the governorate, as it forms a separate administrative unit.'),
(74477, 74477, 'YE', 'Ibb', 'Ibb', 'Ibb', 'ibb', 'Ibb Governorate', null, 13.96667, 44.18333, 771514, false, 'Ibb, Yemen''nın Ibb bölgesinde yer alan bir şehirdir. Şehrin nüfusu 26 Kasım 2009 tarihinde toplam nüfusu 160.000''dir.', 'Ibb is a city in Yemen, the capital of Ibb Governorate, located about 117 km northeast of Mokha and 194 km south of Sanaa.'),
(76184, 76184, 'YE', 'Zamar', 'Dhamar', 'Dhamar', 'zamar|dhamar', 'Dhamār', null, 14.54274, 44.40514, 160114, false, 'Zamar, güney-batı Yemen''de bulunan bir şehirdir.', 'Dhamar is a city in south-western Yemen. It is located at 14°33′0″N 44°24′6″E, at an elevation of around 2,400 m.'),
(78754, 78754, 'YE', 'El-Mukelle', 'Mukalla', 'Mukalla', 'el mukelle|mukalla', 'Muhafazat Hadramaout', null, 14.54248, 49.12424, 594951, false, 'El-Mukelle, Yemen''in Hadramut ilinin yönetim merkezi ve ana limanı konumundadır. Ülkenin 5. büyük şehridir.', 'Mukalla, officially the Mukalla City District, is a seaport and the capital city district of Yemen''s largest governorate, Hadhramaut.'),
(79415, 79415, 'YE', 'Hudeyde', 'Al Hudaydah', 'Al Hudaydah', 'hudeyde|al hudaydah', 'Al Hudaydah', null, 14.79781, 42.95452, 734699, false, 'El-Hudeyde, Yemen''in aynı adlı ilin merkezi olan liman şehri. Ülkenin başlıca dış ticaret limanıdır.', 'Hodeidah, also transliterated as Hodeda, Hodeida, Hudaida or al-Hudaydah, is the fourth-largest city in Yemen, its principal port on the Red Sea, and the capital of Hodeidah Governorate.'),
(81302, 81302, 'LY', 'Tobruk', 'Tobruk', 'Tobruk', 'tobruk', 'Al Butnan', null, 32.08963, 23.95385, 141499, false, 'Tobruk Libya''nın kuzeydoğusunda bulunan önemli bir liman kentidir. Nüfusu tahmini 172,500 civarındadır.', 'Tobruk is a port city on Libya''s eastern Mediterranean coast, near the border with Egypt. It is the capital of the Butnan District and has a population of 120,000.'),
(87205, 87205, 'LY', 'Derne', 'Derna', 'Darnah', 'derne|derna|darnah', 'Darnah', null, 32.76704, 22.63669, 102581, false, 'Derne, Libya''da bir liman şehirdir. Tarihinde Berberi Devletleri''ndeki zengin devletlerden birine başkentlik yapmıştır.', 'Derna is a port city in eastern Libya. With a population of around 111,000, Derna was once the seat of one of the wealthiest provinces among the Barbary States.'),
(88319, 88319, 'LY', 'Bingazi', 'Benghazi', 'Benghazi', 'bingazi|benghazi', 'Banghazi', null, 32.11486, 20.06859, 757490, false, 'Bingazi (Arapça: Akdeniz sahilinde yer alan şehrin nüfusu yaklaşık 1.500.000''dir. Uzun süre Osmanlı idaresinde kalan Bingazi, Trablusgarp Savaşı''ndan sonra 1912 yılında Uşi Anlaşması ile İtalya''ya bırakıldı.', 'Benghazi is the second-largest city in Libya as well as the largest city in Cyrenaica, with an estimated population of 859,000 in 2023.'),
(89055, 89055, 'LY', 'El Bayda', 'Al Bayda', 'Al Bayda''', 'el bayda|al bayda', 'Al Jabal al Akhdar', null, 32.76272, 21.75506, 129439, false, 'El-Beyda (Arapça: البيضاء,', 'Bayda or Elbeida, known as Beda Littoria under Italian colonial rule, is a commercial and industrial city in northern Cyrenaica, eastern Libya.'),
(89113, 89113, 'LY', 'Ecdebiye', 'Ajdabiya', 'Ajdabiya', 'ecdebiye|ajdabiya', 'Al Wahat', null, 30.75545, 20.22625, 131773, false, 'Ecdebiye, Libya''da bir şehirdir. Sirenayka bölgesinde, ülkenin kuzeydoğusunda bulunan şehir El Vahat ilinin merkezidir.', 'Ajdabiya is a town in and capital of the Al Wahat District in northeastern Libya. It is some 150 kilometres south of Benghazi.'),
(89824, 89824, 'IQ', 'Um Kasr', 'Umm Qasr', 'Umm Qasr', 'um kasr|umm qasr', 'Basra', null, 30.0362, 47.91951, 107620, false, 'Um Kasr, Irak''ın güneyinde bir liman kenti. Basra Körfezi''nde oluşmuş Havr Abdullah halici boyunca Basra Körfezi kıyısında kurulmuştur.', 'Umm Qasr is a port city in southern Iraq. It stands on the canalised Khawr az-Zubayr, part of the Khawr Abd Allah estuary which leads to the Persian Gulf.'),
(90026, 90026, 'IQ', 'Tuzhumartu', 'Tuz Khormato', 'Tuz Khurmatu', 'tuzhumartu|tuz khormato|tuz khurmatu', 'Salah ad Din', null, 34.88808, 44.63256, 120712, false, 'Tuzhurmatu Irak''ın Selahaddin ili''ne bağlı şehir. Kerkük''e uzaklığı 70 km, Bağdat''a uzaklığıysa 170 km''dir.', 'Tuz Khurmatu is the central city of Tooz District in Saladin Governorate, Iraq, located 55 miles south of Kirkuk.'),
(90532, 90532, 'IQ', 'Sumayl', 'Sumayl', 'Sumayl', 'sumayl', 'Duhok', null, 36.85823, 42.8482, 152512, false, null, null),
(90708, 90708, 'IQ', 'Sinah', 'Sīnah', 'Sinah', 'sinah', 'Duhok', null, 36.80851, 43.03935, 128776, false, null, null),
(91057, 91057, 'IQ', 'Ash Sharqāt', 'Ash Sharqāt', 'Ash Sharqat', 'ash sharqat', 'Salah ad Din', null, 35.51722, 43.22806, 160000, false, null, null),
(91597, 91597, 'IQ', 'Samarra', 'Samarra', 'Samarra''', 'samarra', 'Salah ad Din', null, 34.1959, 43.88568, 158508, false, 'Samarra, Irak''ta Bağdat''ta bir şehir. Bağdat''ın 125 kilometre kuzeyinde, Selahaddin Eyaleti''nde Dicle Nehri''nin doğu kıyısında yer alır.', 'Samarra is a city in Iraq. It stands on the east bank of the Tigris in the Saladin Governorate, 125 kilometers north of Baghdad.'),
(92052, 92052, 'IQ', 'Raniye', 'Ranya', 'Ranyah', 'raniye|ranya|ranyah', 'Sulaymaniyah', null, 36.25511, 44.88239, 114173, false, 'Raniye, Irak''ın kuzeyinde, Kürdistan Bölgesel Yönetimi''nde yer alan Süleymaniye İlindeki Süleymaniye''nin 130 km kuzeybatısında bir şehir.', 'Ranya is a town located in the Kurdistan Region of Iraq, and is part of the Sulaymaniyah Governorate. The town and its inhabitants are well known for their involvement in the 1991 Uprising against Ba''athist Iraq.'),
(92511, 92511, 'IQ', 'Qal‘at Sukkar', 'Qal‘at Sukkar', 'Qal''at Sukkar', 'qal at sukkar', 'Dhi Qar', null, 31.8632, 46.07321, 110000, false, null, null),
(92615, 92615, 'IQ', 'Qeładizê', 'Qeładizê', 'Qeladize', 'qeladize', 'Sulaymaniyah', null, 36.18254, 45.13017, 140688, false, null, null),
(94591, 94591, 'IQ', 'Hanekin', 'Khanaqin', 'Khanaqin', 'hanekin|khanaqin', 'Diyala', null, 34.3482, 45.39065, 175000, false, 'Hanekin, Irak''ta Diyala ilinde bir şehir. İran sınırı yakınında bulunur.', 'Khanaqin is the central city of Khanaqin District in Diyala Governorate, Iraq, near the Iranian border on the Alwand tributary of the Diyala River.'),
(94787, 94787, 'IQ', 'Kerkük', 'Kirkuk', 'Kirkuk', 'kerkuk|kirkuk', 'Kirkuk', null, 35.46806, 44.39222, 1031000, false, 'Kerkük, Irak''taki Kerkük ilinin başkenti olan şehirdir. Irak merkezi yönetimine bağlıdır.', 'Kirkuk is a major city in northern Iraq, serving as the capital of the Kirkuk Governorate. The city is home to a diverse population of Kurds, Iraqi Turkmens and Arabs, as well as smaller numbers of Assyrians.'),
(94824, 94824, 'IQ', 'Kerbela', 'Karbala', 'Karbala', 'kerbela|karbala', 'Karbala', null, 32.61603, 44.02488, 1218732, false, 'Kerbela, Irak''ın merkezindeki önemli bir şehirdir. Kerbela ili''nin başkentidir.', 'Karbala is a major city in Iraq, and the capital of Karbala Governorate. With a population of around 800,000 people in 2024, Karbala is the second-largest city in central Iraq, after Baghdad.'),
(95005, 95005, 'IQ', 'Kelar', 'Kelar', 'Kelar', 'kelar', 'Sulaymaniyah', null, 34.62805, 45.31852, 250000, false, null, null),
(95446, 95446, 'IQ', 'Erbil', 'Erbil', 'Erbil', 'erbil', 'Erbil', null, 36.19117, 44.00943, 1612700, false, 'Erbil, Irak''ın Kürdistan Bölgesel Yönetimi''nin başkenti ve en kalabalık şehri olan Erbil ili''nin de başkentidir.', 'Erbil, also called Hawler, is the capital and most populated city in the Kurdistan Region of Iraq and the capital of the Erbil Governorate.'),
(96833, 96833, 'IQ', 'Xebat', 'Xebat', 'Xebat', 'xebat', 'Erbil', null, 36.27798, 43.67065, 148047, false, null, null),
(96994, 96994, 'IQ', 'Duhok', 'Duhok', 'Dihok', 'duhok|dihok', 'Duhok', null, 36.86608, 42.9879, 340900, false, 'Duhok, Irak''ın kuzeyinde bir şehir ve Kürdistan Bölgesel Yönetimi''ne bağlı Duhok ilinin başkenti. 500.000 yakın nüfusu vardır ve çoğunluğunu Kürtler ve Süryaniler oluşturur.', 'Duhok is a city in Kurdistan Region, Iraq and the capital city of Duhok Governorate.'),
(97783, 97783, 'IQ', 'Beyci', 'Baiji', 'Bayji', 'beyci|baiji|bayji', 'Salah ad Din', null, 34.92915, 43.48878, 173677, false, null, 'Baiji is a city of about 173,677 inhabitants in Salah ad Din governorate in northern Iraq. It is located some 130 miles north of Baghdad, on the main road to Mosul.'),
(97990, 97990, 'IQ', 'Bakuba', 'Baqubah', 'Baqubah', 'bakuba|baqubah', 'Diyala', null, 33.75403, 44.60518, 152550, false, 'Bakube Irak''ta bir şehir ve Diyala ili''nin başkenti. Şehir, Bağdat''ın 50 kilometre kuzeydoğusunda yer alır, Diyala Nehri''nin üzerindedir.', 'Baqubah is the capital of the Diyala Governorate of Iraq. The city is located some 50 km to the northeast of Baghdad, on the Diyala River.'),
(98156, 98156, 'IQ', 'Baḥarkah', 'Baḥarkah', 'Baharkah', 'baharkah', 'Erbil', null, 36.31556, 44.03533, 130518, false, null, null),
(98182, 98182, 'IQ', 'Bağdat', 'Baghdad', 'Baghdad', 'bagdat|baghdad', 'Baghdad', null, 33.34058, 44.40088, 7216000, true, 'Bağdat, Irak''ın başkenti ve en büyük şehridir. Irak''ın merkezinde, Dicle Nehri kıyısında yer almaktadır.', 'Baghdad is the capital and the largest city of Iraq. It is located on the banks of the Tigris in central Iraq.'),
(98245, 98245, 'IQ', 'Ez-Zubeyr', 'Az Zubayr', 'Az Zubayr', 'ez zubeyr|az zubayr', 'Basra', null, 30.39213, 47.70175, 122676, false, null, 'Az Zubayr is a city in and the capital of Al-Zubayr District, part of the Basra Governorate of Iraq. The city is just south of Basra.'),
(98463, 98463, 'IQ', 'Süleymaniye', 'Sulaymaniyah', 'Sulaymaniyah', 'suleymaniye|sulaymaniyah', 'Sulaymaniyah', null, 35.56496, 45.4329, 878146, false, 'Süleymaniye, Irak''ın Kürdistan Bölgesel Yönetimi''nin Süleymaniye İline bağlı şehir ve ilin yönetim merkezidir.', 'Sulaymaniyah or Slemani, is a city in the east of the Kurdistan Region of Iraq and is the capital of the Sulaymaniyah Governorate.'),
(98530, 98530, 'IQ', 'Semave', 'Samawah', 'As Samawah', 'semave|samawah|as samawah', 'Muthanna', null, 31.33198, 45.2944, 152890, false, 'Semave Irak''ın Müsenna Vilayeti''nde şehir. Bağdat''ın 280 kilometre güneydoğusunda yer alır.', 'Samawah or As-Samawah is a city in Iraq, 280 kilometres southeast of Baghdad.'),
(98622, 98622, 'IQ', 'Ash Shatrah', 'Ash Shatrah', 'Ash Shatrah', 'ash shatrah', 'Dhi Qar', null, 31.40906, 46.1727, 182175, false, null, 'Al-Shatrah is a town in southern Iraq, located north of Nasiriyah. It is the administrative capital of the Al-Shatra District, a part of the Dhi Qar Governorate.'),
(98717, 98717, 'IQ', 'Ramadi', 'Ramadi', 'Ramadi', 'ramadi', 'Anbar', null, 33.42056, 43.30778, 223500, false, 'Ramâdî, Irak''ta bir şehir. Bağdat''ın 110 kilometre batısında yer alır.', 'Ramadi is a city in central Iraq, about 110 kilometers west of Baghdad and 50 kilometers west of Fallujah. It is the capital and largest city of Al Anbar Governorate which shares borders with Syria, Jordan, and Saudi Arabia.'),
(98846, 98846, 'IQ', 'An Numaniyah', 'An Numaniyah', 'An Nu''maniyah', 'an numaniyah|an nu maniyah', 'Wasit', null, 32.55621, 45.41293, 110000, false, null, 'An-Nu''mānīyah is a city on the Tigris river in Iraq, located roughly 140 kilometres southeast of Baghdad in the Wasit Province.'),
(98854, 98854, 'IQ', 'Nasiriye', 'Nasiriyah', 'Nasiriyah', 'nasiriye|nasiriyah', 'Dhi Qar', null, 31.05799, 46.25726, 558400, false, 'Nasıriye Irak''ın Zi Kar ilinin merkezi olan şehirdir. Şehir, Fırat Nehri''nin kıyısında yer almakta olup Bağdat''ın 370 km güneydoğusunda yer alır.', 'Nasiriyah, also spelled Nassiriya or Nasiriya, is a city in Iraq, the capital of the Dhi Qar Governorate. It lies on the lower Euphrates, about 360 km south-southeast of Baghdad, near the ruins of the ancient city of Ur, as well as the recently established Ur Tourist City located adjacent to the archaeological site.'),
(98860, 98860, 'IQ', 'Necef', 'Najaf', 'Najaf', 'necef|najaf', 'Najaf', null, 32.02594, 44.34625, 482576, false, 'Necef, Irak''ın başkenti Bağdat''ın 160 km güneyinde bulunan şehir. Çoğunluğunu Şiilerin oluşturduğu şehrin nüfusu 2019 itibarıyla 847.000''dir.', 'Najaf is the capital city of the eponymous Najaf Governorate in central Iraq, about 160 km south of Baghdad. Its estimated population in 2024 was about 1.41 million people.'),
(98993, 98993, 'IQ', 'El Kurna', 'Al-Qurnah', 'Al Qurnah', 'el kurna|al qurnah', 'Basra', null, 31.01547, 47.43362, 134174, false, 'El-Kurne, Irak''ın Basra iline bağlı aynı isimli ilçede yer alan ve ilçenin merkezi olan şehirdir. Basra''nın 74 km kuzey batısında, Dicle ve Fırat''ın birleşerek Şattülarap''ı oluşturdukları yerde yer alır.', 'Al-Qurnah is a town in southern Iraq about 74 km northwest of Basra, that lies within the conglomeration of Nahairat.'),
(99039, 99039, 'IQ', 'Musayyib', 'Musayyib', 'Al-Musayab', 'musayyib|al musayab', 'Babil', null, 32.77872, 44.29005, 101873, false, 'Musayyib, Irak''ta yer alan bir şehirdir. 2018 yılı itibarıyla nüfusu 57.300''dür.', 'Musayyib is an increasing majority Shia Arab town in the Babil Province, Iraq. As of 2018, its population was 57,300.'),
(99062, 99062, 'IQ', 'Muqdadiyah', 'Muqdadiyah', 'Al Miqdadiyah', 'muqdadiyah|al miqdadiyah', 'Diyala', null, 33.97861, 44.93694, 155968, false, null, 'Miqdadiyah is a city in the Diyala Governorate of Iraq. Its population is a mix of Arab, Kurdish and Turkmen.'),
(99072, 99072, 'IQ', 'Musul', 'Mosul', 'Mosul', 'musul|mosul', 'Nineveh', null, 36.335, 43.11889, 1683000, false, 'Musul, Irak''ın kuzeyindeki önemli bir şehirdir ve Ninova Valiliği''nin başkentidir. Başkent Bağdat''tan sonra Irak''ın ikinci büyük şehridir ve Dicle Nehri kıyısında yer almaktadır.', 'Mosul is a major city in northern Iraq, serving as the capital of Nineveh Governorate. It is the second largest city in Iraq overall after the capital Baghdad.'),
(99100, 99100, 'IQ', 'Al Maḩmūdīyah', 'Al Maḩmūdīyah', 'Al Mahmudiyah', 'al mahmudiyah', 'Baghdad', null, 33.06221, 44.36564, 122384, false, null, null),
(99106, 99106, 'IQ', 'Al Madīnah', 'Al Madīnah', 'Al Madinah', 'al madinah', 'Basra', null, 30.96324, 47.26998, 255000, false, null, null),
(99131, 99131, 'IQ', 'Kutülamare', 'Kut', 'Al-Kut', 'kutulamare|kut|al kut', 'Wasit', null, 32.5128, 45.81817, 315162, false, 'Kut, resmî adıyla El-Kut, Irak''ın doğu kesiminde, Dicle Nehri kıyısında yer alan Vasıt ilinin merkezi kent. 1960''a kadar tüm il bu isimle anılırken bu tarihten sonra Vasıt adını almıştır.', 'Kūt, officially Al-Kut, also spelled Kutulamare, Kut al-Imara or Kut Al Amara, is a city in eastern Iraq, on the left bank of the Tigris River, about 160 kilometres south east of Baghdad, and the capital of the Wasit Governorate.'),
(99135, 99135, 'IQ', 'Kufe', 'Kufa', 'Kufa', 'kufe|kufa', 'Najaf', null, 32.05114, 44.44017, 110000, false, 'Kûfe, Irak''ın Necef ilinde bir şehir.', 'Kufa, also spelled Kufah, is a city in Iraq, about 170 kilometres south of Baghdad, and 10 kilometres northeast of Najaf.'),
(99226, 99226, 'IQ', 'İskenderiye', 'Iskandariya', 'Nahiyat al Iskandariyah', 'iskenderiye|iskandariya|nahiyat al iskandariyah', 'Babil', null, 32.8873, 44.34619, 100600, false, 'İskenderiye, Irak''ın Babil ilinde bulunan bir şehirdir. Şehir, başkent Bağdat''ın 70 km güneyinde Fırat Nehri''nin kıyısında yer almaktadır.', 'Al-Iskandariya or Alexandria is an ancient city in central Iraq, one of a number of towns in the Near East founded by and named after Alexander the Great.'),
(99344, 99344, 'IQ', 'Al-Hindiya', 'Al-Hindiya', 'Al Hindiyah', 'al hindiya|al hindiyah', 'Karbala', null, 32.54193, 44.22469, 139578, false, null, 'Al-Hindiya or Hindiya lit. "The Indian" is a city in Iraq on the Euphrates River.'),
(99347, 99347, 'IQ', 'Hilla', 'Hillah', 'Al Hillah', 'hilla|hillah|al hillah', 'Babil', null, 32.46367, 44.41963, 455700, false, 'El-Hille, Irak''ın merkezinde Fırat Nehri üzerinde bir şehir. Bağdat''ın 100 km güneyinde yer alır.', 'Hillah, also spelled Hilla, is a city in central Iraq. On the Hilla branch of the Euphrates River, it is 100 km south of Baghdad.'),
(99446, 99446, 'IQ', 'El-Fav', 'Al-Faw', 'Al Faw', 'el fav|al faw', 'Basra', null, 29.97421, 48.47309, 104569, false, 'El-Fav, Irak''ın Basra ilinde bulunan bir şehirdir. Şehrin nüfusu 2005 yılı itibarı ile 105,080''dir.', 'Al-Fāw is a port town on Al-Faw Peninsula in Iraq near the Shatt al-Arab and the Persian Gulf. The Al Faw Peninsula is part of the Basra Governorate.'),
(99454, 99454, 'IQ', 'Felluce', 'Fallujah', 'Al Fallujah', 'felluce|fallujah|al fallujah', 'Anbar', null, 33.34913, 43.78599, 190159, false, 'Felluce; başkent Bağdat''ın 70 km batısında Fırat Nehri kenarında yer alan, Irak''ın El-Anbar iline bağlı kasaba.', 'Fallujah is a city in Al Anbar Governorate, Iraq. Situated on the Euphrates River, it is located roughly 69 kilometres to the west of the capital city of Baghdad and 50 kilometres from the neighboring city of Ramadi.'),
(99532, 99532, 'IQ', 'Basra', 'Basra', 'Basrah', 'basra|basrah', 'Basra', null, 30.50852, 47.7804, 1326564, false, 'Basra, Irak''ın güneyinde bir liman şehridir. Adını aldığı Basra Valiliği''nin başkenti ve Bağdat ile Musul''dan sonra Irak''ın üçüncü büyük şehridir.', 'Basra or Basrah is a port city in southern Iraq. It is the capital of the eponymous Basra Governorate, as well as the third largest city in Iraq overall, behind Baghdad and Mosul.'),
(99608, 99608, 'IQ', 'Amare', 'Amarah', 'Al ''Amarah', 'amare|amarah|al amarah', 'Maysan', null, 31.83561, 47.14483, 323302, false, 'Amara veya Amare, Irak''ın güneydoğusunda şehir. Başkent Bağdat''ın 50 km. güneyinde, 31°50′N 47°09′E koordinatlarındadır.', 'Amarah, also spelled Amara, is a city in south-eastern Iraq, located on a low ridge next to the Tigris River waterway south of Baghdad about 50 km from the border with Iran.'),
(99762, 99762, 'IQ', 'Divaniye', 'Al Diwaniyah', 'Al Diwaniyah', 'divaniye|al diwaniyah', 'Al-Qadisiyah', null, 31.99289, 44.92552, 318801, false, 'Divaniye, Irak''ın Kadisiye ilinin başkentidir. 2002 yılındaki verilere göre nüfusu 420.000''dir.', 'Al Diwaniyah, also spelt Diwaniya, is the capital city of Iraq''s Al-Qādisiyyah Governorate. In 2014 the population was estimated at 700,000.'),
(100077, 100077, 'IQ', 'Abu Ghraib', 'Abu Ghraib', 'Abu Ghurayb', 'abu ghraib|abu ghurayb', 'Baghdad', null, 33.30563, 44.18477, 900000, false, null, 'Abu Ghraib is a city in the Baghdad Governorate of Iraq, located just west of Baghdad''s city center, or northwest of Baghdad International Airport.'),
(100425, 100425, 'SA', 'Yanbu governorate', 'Yanbu governorate', 'Yanbu', 'yanbu governorate|yanbu', 'Medina Region', null, 24.08954, 38.0618, 200161, false, null, 'Governorate in Saudi Arabia'),
(101628, 101628, 'SA', 'Tebük', 'Tabuk', 'Tabuk', 'tebuk|tabuk', 'Tabuk Region', null, 28.3998, 36.57151, 667000, false, 'Tebük, kuzeybatı Arap Yarımadası''nda Suudi Arabistan''ın Tebük Bölgesi''nin bir ana şehridir.', 'Tabuk is a city in northwestern Saudi Arabia, and the capital of Tabuk Province. It is located near the Jordan–Saudi Arabia border.'),
(101732, 101732, 'SA', 'Unaizah', 'Unaizah', 'Unaizah', 'unaizah', 'Al-Qassim Region', null, 26.1, 44, 183319, false, null, null),
(101760, 101760, 'SA', 'Sultanah', 'Sultanah', 'Sultanah', 'sultanah', 'Medina Region', null, 24.49258, 39.58572, 946697, false, null, 'Sultanah is a street with various restaurants and shops in Al Madinah Province, in western Saudi Arabia.'),
(102527, 102527, 'SA', 'Sekake', 'Sakakah', 'Sakakah', 'sekake|sakakah', 'Al Jawf Region', null, 29.96974, 40.20641, 128332, false, 'Sekaka, Suudi Arabistan''ın Cevf Bölgesi''nde şehir ve valilik.', 'Sakākā, often spelled Sakakah is a city in northwestern Saudi Arabia which is the capital of Al-Jawf Province.'),
(102651, 102651, 'SA', 'Sabya governorate', 'Sabya governorate', 'Sabya', 'sabya governorate|sabya', 'Jazan Region', null, 17.1495, 42.62537, 228375, false, null, 'Sabya Governorate is one of the governorates in Jazan Region, Saudi Arabia. Its seat is the city of Sabya.'),
(103369, 103369, 'SA', 'Bişa', 'Bisha', 'Bishah', 'bisa|bisha|bishah', '''Asir Region', null, 20.00054, 42.6052, 115537, false, 'Bişa veya Kalet Bişa, Suudi Arabistan''ın Asir Bölgesi''nde bulunan bir şehirdir. Şehrin nüfusu 2010 yılı itibarı ile 205,346''dır.', 'Bisha, also known as Qal`at Bishah, is a town in the south-western Saudi Arabian province, Asir. Bisha was its own province before merging with its neighboring province, Asir.'),
(103630, 103630, 'SA', 'Necran', 'Najran', 'Najran', 'necran|najran', 'Najran Region', null, 17.49326, 44.12766, 505652, false, 'Necran, Suudi Arabistan''ın Necran Bölgesi''nin merkezi olan şehirdir. Şehir, ülkenin güneybatısında Yemen sınırı yakınlarında yer almaktadır.', 'Najran, is a city in southwestern Saudi Arabia. It is the capital of Najran Province.'),
(104515, 104515, 'SA', 'Mekke', 'Mecca', 'Makkah', 'mekke|mecca|makkah', 'Mecca Region', null, 21.42664, 39.82563, 1578722, false, 'Mekke ya da Mekke-i Mükerreme, bugünkü Suudi Arabistan''nın tarihî Hicaz''ında Mekke Bölgesi''nin yönetim merkezi olan şehirdir.', 'Mecca, officially Makkah al-Mukarramah, is a city in the Hejaz region of western Saudi Arabia and is the capital of Mecca Province.'),
(105072, 105072, 'SA', 'Hamis Muşayt', 'Khamis Mushait', 'Khamis Mushait', 'hamis musayt|khamis mushait', '''Asir Region', null, 18.3, 42.73333, 387553, false, 'Hamis Muşayt, Suudi Arabistan''ın Asir Bölgesi''nde bulunan bir şehirdir. Şehir, ülkenin güneybatısında yer almaktadır.', 'Khamis Mushayt or Khamis Mushait is a city in south-west Saudi Arabia, located east of Abha, the provincial seat of the Asir Province 884 kilometres from the national capital of Riyadh.'),
(105299, 105299, 'SA', 'Cizan', 'Jizan', 'Jizan', 'cizan|jizan', 'Jazan Region', null, 16.88917, 42.55111, 105198, false, 'Cizan, Suudi Arabistan''ın Cizan Bölgesi''nin merkezi olan şehirdir. Şehir, Kızıldeniz''in kıyısında Farasan Adası''nın karşısında yer almaktadır.', 'Jizan is a city and the capital of Jazan Province, which lies in the southwest corner of Saudi Arabia. Jizan is situated on the coast of the Red Sea and serves a large agricultural heartland that has a population of 173,919 as of 2022 and over 1.4 million, in the whole Jizan region.'),
(105343, 105343, 'SA', 'Cidde', 'Jeddah', 'Jeddah', 'cidde|jeddah', 'Mecca Region', null, 21.49012, 39.18624, 4697000, false, 'Cidde, Suudi Arabistan''ın Hicaz bölgesinde, Kızıldeniz kıyısında yer almaktadır. Bir valilik görevi gören Cidde, Mekke vilayetinin en büyük şehridir ve başkent Riyad''dan sonra ülkenin ikinci büyük şehridir.', 'Jeddah is the largest city in Mecca Province, the second-largest city in Saudi Arabia after Riyadh, and the country''s main commercial center.'),
(106281, 106281, 'SA', 'Hail', 'Ha''il', 'Ha''il', 'hail|ha il', 'Ha''il Region', null, 27.52188, 41.69073, 605930, false, 'Hail, Suudi Arabistan''ın Hail Bölgesi''nin merkezi olan şehirdir. Şehrin nüfusu 2010 itibarıyla 412,758''dir.', 'Hail is a city in north-western Saudi Arabia, located between the Shammar Mountains of Aja and Salma. It is the seat and largest city of Hail Province.'),
(106297, 106297, 'SA', 'Hafar Al-Batin governorate', 'Hafar Al-Batin governorate', 'Hafar Al-Batin', 'hafar al batin governorate|hafar al batin', 'Eastern Province', null, 28.43279, 45.97077, 271642, false, null, 'Governorate in Saudi Arabia'),
(107304, 107304, 'SA', 'Bureyde', 'Burayda', 'Buraydah', 'bureyde|burayda|buraydah', 'Al-Qassim Region', null, 26.32599, 43.97497, 745353, false, 'Büreyde, Suudi Arabistan''ın El Kasım Bölgesi''nin merkezi olan şehirdir. Şehir, ülkenin kuzeyinin ortasında yer almaktadır.', 'Buraidah is the capital and largest city of Al-Qassim Province in north-central Saudi Arabia. The city is regarded as the agricultural capital of Saudi Arabia and has been described as the Kingdom''s breadbasket due to the diversity of its produce.'),
(107781, 107781, 'SA', 'Az Zulfi', 'Az Zulfi', 'Az Zulfi', 'az zulfi', 'Riyadh Region', null, 26.29945, 44.81542, 125000, false, null, null),
(107968, 107968, 'SA', 'Taif', 'Ta''if', 'Ta''if', 'taif|ta if', 'Mecca Region', null, 21.27028, 40.41583, 688693, false, 'Taif, Suudi Arabistan''ın Mekke Bölgesi''nde bir şehir.', 'Taif is a city and governorate in Mecca Province in Saudi Arabia. Located at an elevation of 1,879 m in the slopes of the Hijaz Mountains, which themselves are part of the Sarat Mountains, the city has a population of 563,282 people in 2022, making it one of the most populous cities in the kingdom.'),
(108410, 108410, 'SA', 'Riyad', 'Riyadh', 'Riyadh', 'riyad|riyadh', 'Riyadh Region', null, 24.68773, 46.72185, 4205961, true, 'Riyad, Suudi Arabistan''ın başkenti ve en büyük şehridir. Aynı zamanda Riyad Eyaleti''nin başkenti ve Riyad Valiliği''nin merkezidir.', 'Riyadh is the capital and largest city of Saudi Arabia, as well as the largest city on the Arabian Peninsula. It serves as the administrative capital of both the Riyadh Province and the Riyadh Emirate.'),
(108512, 108512, 'SA', 'Arar', 'Arar', 'Arar', 'arar', 'Northern Borders Region', null, 30.97531, 41.03808, 148540, false, 'Arar, Suudi Arabistan''da Kuzey Sınır Bölgesi''nin merkezi olan şehir.', 'Arar is a city in northern Saudi Arabia. It is the seat of the Northern Borders Province.'),
(108648, 108648, 'SA', 'Kureyyet', 'Qurayyat', 'Qurayyat', 'kureyyet|qurayyat', 'Al Jawf Region', null, 31.33176, 37.34282, 102903, false, 'Kureyyet, Suudi Arabistan''ın Cevf Bölgesi''nde şehir ve valilik. Kurayyat şehri, Cevf Bölgesi''nin 4 vilayetinden birisi olan aynı isimli Kurayyat Vilayeti''nin yönetim merkezi olan şehrin 2010 yılı nüfusu 147.450''dir.', 'Qurayyat is a governorate in Al-Jouf Province, northern Saudi Arabia. Its administrative centre is the city of Qurayyat.'),
(109101, 109101, 'SA', 'Al-Mubarraz', 'Al-Mubarraz', 'Al Mubarraz', 'al mubarraz', 'Eastern Province', null, 25.40768, 49.59028, 290802, false, null, 'Al-Mubarraz is a city located at Al-Ahsa in the Eastern Province of the Kingdom of Saudi Arabia. With a population of 837,000, it is the north gate for Al-Ahsa governorate.'),
(109223, 109223, 'SA', 'Medine', 'Medina', 'Madinah', 'medine|medina|madinah', 'Medina Region', null, 24.46861, 39.61417, 1300000, false, 'Medine, resmî adıyla Medine-i Münevvere, bilinen adlarıyla el-Medînetü''n-Nebeviyye ya da Taybe, İslam öncesi dönemde Yesrib adıyla anılan, Suudi Arabistan''ın batısındaki Hicaz bölgesinde yer alan, Medine Bölgesi''nin başkenti ve idari merkezidir.', 'Medina, officially al-Madinah al-Munawwarah, also known as al-Madinah an-Nabawiyyah and Taybah, is the capital, administrative centre, and largest city of Medina Province in the Hejaz region of western Saudi Arabia.'),
(109323, 109323, 'SA', 'El Huber', 'Khobar', 'Khobar', 'el huber|khobar', 'Eastern Province', null, 26.27944, 50.20833, 165799, false, 'El Huber, Suudi Arabistan''ın doğusunda, Bahreyn''e yakın bir şehirdir.', 'Al Khobar is a city and governorate in the Eastern Province of the Kingdom of Saudi Arabia, situated on the coast of the Persian Gulf.'),
(109353, 109353, 'SA', 'El-Harc', 'Al-Kharj', 'Al Kharj', 'el harc|al kharj', 'Riyadh Region', null, 24.15541, 47.33457, 425300, false, null, 'Al-Kharj or Kharj is a governorate in Riyadh Province, Saudi Arabia. It is located 83 km southeast of the capital city, and has the second-largest population in the province.'),
(109435, 109435, 'SA', 'Jubail', 'Jubail', 'Al Jubayl', 'jubail|al jubayl', 'Eastern Province', null, 27.0174, 49.62251, 237274, false, null, 'City in Saudi Arabia'),
(109571, 109571, 'SA', 'Al Hufūf', 'Al Hufūf', 'Al Hufuf', 'al hufuf', 'Eastern Province', null, 25.36467, 49.58764, 293179, false, null, null),
(110336, 110336, 'SA', 'Ad Dammam', 'Dammam', 'Dammam', 'ad dammam|dammam', 'Eastern Province', null, 26.43442, 50.10326, 1252523, false, 'Ed-Dammam, Suudi Arabistan''da El Huber şehir merkezinin 15 km kuzeybatısında olan bir ilçe. El Huber şehrinin ünlü limanı ve deniz feneri bu bölgede yer alır.', 'Dammam is the seat and largest city of the Eastern Province of Saudi Arabia. An industrial port city on the coast of the Persian Gulf, it had a population of 1,386,166 as of 2022, making it the country''s fifth-largest city after Riyadh, Jeddah, Mecca, and Medina.'),
(110690, 110690, 'SA', 'Ebha', 'Abha', 'Abha', 'ebha|abha', '''Asir Region', null, 18.21639, 42.50528, 210886, false, 'Abha, Suudi Arabistan''ın, Asir Bölgesi''nde bulunan 2004 yılı sayımına göre şehiriçi 201.912, genel olarak 252.126 nüfuslu bir şehirdir.', 'Abha is the capital of Asir Province in Saudi Arabia. It is situated 2,270 metres above sea level in the fertile Asir Mountains of south-western Saudi Arabia, near Asir National Park.'),
(111453, 111453, 'IR', 'Zencan', 'Zanjan', 'Zanjan', 'zencan|zanjan', 'Zanjan', null, 36.67642, 48.49628, 357471, false, 'Zencan, İran''ın ve Azerbaycan''ın aynı isimli Zencan eyaletinin yönetim merkezi olan şehirdir.', 'Zanjan is a city in the Central District of Zanjan County, Zanjan province, Iran, serving as capital of the province, the county, and the district.Zanjan''s population boasts the highest level of happiness among the people of 30 other provinces in Iran, according to a detailed survey conducted by Isna.'),
(111822, 111822, 'IR', 'Yezd', 'Yazd', 'Yazd', 'yezd|yazd', 'Yazd Province', null, 31.89722, 54.3675, 477905, false, 'Yezd, İran''ın orta kısmında, Yezd Eyaleti''nin yönetim merkezi olan şehir.', 'Yazd is a city in the Central District of Yazd County, Yazd province, Iran, serving as capital of the province, the county, and the district.'),
(112214, 112214, 'IR', 'Veramin', 'Varamin', 'Varamin', 'veramin|varamin', 'Tehran', null, 35.3242, 51.6457, 225628, false, 'Veramin, İran''ın Tahran Eyaleti''nde şehir.', 'Varamin is a city in the Central District of Varamin County, Tehran province, Iran, serving as capital of both the county and the district.'),
(112646, 112646, 'IR', 'Türbet Haydariye', 'Torbat-e Heydarieh', 'Torbat-e Heydariyeh', 'turbet haydariye|torbat e heydarieh|torbat e heydariyeh', 'Razavi Khorasan', null, 35.27401, 59.21949, 140019, false, 'Türbet Haydariye, İran''ın Razavi Horasan Eyaleti''nde şehir.', 'Torbat-e Heydarieh is a city in the Central District of Torbat-e Heydarieh County, Razavi Khorasan province, Iran, serving as capital of both the county and the district.'),
(112931, 112931, 'IR', 'Tahran', 'Tehran', 'Tehran', 'tahran|tehran', 'Tehran', null, 35.69439, 51.42151, 7153309, true, 'Tahran, İran''ın başkenti ve en büyük şehridir. Aynı zamanda Tahran eyaletinin başkenti ve Tahran İlçesi ile Merkez Bölgesi''nin idari merkezidir.', 'Tehran is the capital and largest city of Iran. It is also the capital of Tehran province and the administrative center for Tehran County and its Central District.'),
(113646, 113646, 'IR', 'Tebriz', 'Tabriz', 'Tabriz', 'tebriz|tabriz', 'East Azerbaijan', null, 38.08, 46.2919, 1424641, false, 'Tebriz, İran''da Güney Azerbaycan bölgesinde yer alan, Doğu Azerbaycan Eyaleti''nin yönetim merkezi olan şehir. Tebriz İran''ın kuzey batısındaki en büyük şehri, aynı zamanda Azerbaycan Türkleri''nin yoğunluklu olarak yaşadığı bir şehirdir.', 'Tabriz is a city in the Central District of Tabriz County, in East Azerbaijan province of northwestern Iran. It serves as capital of the province, the county, and the district.'),
(114259, 114259, 'IR', 'Sircan', 'Sirjan', 'Sirjan', 'sircan|sirjan', 'Kerman', null, 29.45137, 55.6809, 199704, false, 'Sircan, İran''ın Kirman Eyaleti''nde şehir.', 'Sirjan is a city in the Central District of Sirjan County, Kerman province, in southern Iran, serving as capital of both the county and the district.'),
(114584, 114584, 'IR', 'Şüşter', 'Shushtar', 'Shushtar', 'suster|shushtar', 'Khuzestan', null, 32.04972, 48.84843, 101878, false, 'Şuşter, İran''ın Huzistan Eyaleti''nde şehir.', 'Shoushtar is a city in the Central District of Shoushtar County, Khuzestan province, Iran, serving as capital of both the county and the district.'),
(115019, 115019, 'IR', 'Şiraz', 'Shiraz', 'Shiraz', 'siraz|shiraz', 'Fars', null, 29.61031, 52.53113, 1249942, false, 'Şiraz, İran''ın beşinci en kalabalık şehri ve tarihsel olarak Persia olarak bilinen Fars eyaletinin başkentidir.', 'Shiraz is the fifth-most-populous city of Iran and the capital of Fars province, which is historically known by the exonym Persia proper.'),
(115770, 115770, 'IR', 'Şehrikürd', 'Shahr-e Kord', 'Shahr-e Kord', 'sehrikurd|shahr e kord', 'Chaharmahal and Bakhtiari', null, 32.32612, 50.8572, 129153, false, 'Şehrekürd, İran''ın orta-batı kesiminde Çaharmahal ve Bahtiyari eyaletinin merkezi olan şehirdir.', 'Shahr-e Kord is a city in the Central District of Shahrekord County, Chaharmahal and Bakhtiari province, Iran, serving as capital of the province, the county, and the district.'),
(116402, 116402, 'IR', 'Simnan', 'Semnan', 'Semnan', 'simnan|semnan', 'Semnan', null, 35.57691, 53.39205, 124826, false, 'Simnan,İran''da Semnan Eyaleti''nin yönetim merkezi olan şehir.', 'Semnan is a city in the Central District of Semnan County, Semnan province, Iran, serving as capital of the province, the county and the district.'),
(116667, 116667, 'IR', 'Save', 'Saveh', 'Saveh', 'save|saveh', 'Markazi', null, 35.0213, 50.3566, 220762, false, 'Save, İran''ın Merkezi Eyaleti''nde şehir.', 'Saveh is a city in the Central District of Saveh County, Markazi province, Iran, serving as capital of both the county and the district.'),
(116996, 116996, 'IR', 'Sari', 'Sari', 'Sari', 'sari', 'Māzandarān', null, 36.56332, 53.06009, 255396, false, 'Sari, İran''ın kuzeyinde bulunan Mazenderan''ın merkezi olan şehirdir.', 'Sari is a city in the Central District of Sari County, Mazandaran province, serving as capital of the district, county, and province.'),
(117392, 117392, 'IR', 'Saggız', 'Saqqez', 'Saqqez', 'saggiz|saqqez', 'Kurdistan Province', null, 36.24992, 46.2735, 165258, false, 'Sakkız, İran''ın Kürdistan Eyaleti''nde şehir.', 'Saqqez is a city in the Central District of Saqqez County, Kurdistan province, Iran, serving as capital of both the county and the district.'),
(117574, 117574, 'IR', 'Senendec', 'Sanandaj', 'Sanandaj', 'senendec|sanandaj', 'Kurdistan Province', null, 35.31495, 46.99883, 349176, false, 'Senendec, İran''ın Kürdistan Eyaleti''nin yönetim merkezi olan şehir.', 'Sanandaj is a city in the Central District of Sanandaj County, in the Kurdistan province of Iran, serving as capital of the province, the county, and the district.'),
(118063, 118063, 'IR', 'Sebzevar', 'Sabzevar', 'Sabzevar', 'sebzevar|sabzevar', 'Razavi Khorasan', null, 36.2126, 57.68191, 243700, false, 'Sebzevar, İran''ın Razavi Horasan Eyaleti''nde şehir.', 'Sabzevar is a city in northeastern Iran. It is located in the Central District of Sabzevar County, Razavi Khorasan province, serving as the capital of both the county and the district.'),
