(1256287, 1256287, 'IN', 'Silchar', 'Silchar', 'Silchar', 'silchar', 'Assam', null, 24.82733, 92.79787, 178865, false, null, 'Silchar is a city and the headquarters of the Cachar district of the state of Assam, India. It is second largest city of Assam after Guwahati in terms of population and GDP.'),
(1256320, 1256320, 'IN', 'Sikar', 'Sikar', 'Sikar', 'sikar', 'Rajasthan', null, 27.61206, 75.13996, 244497, false, null, 'Sikar is a city and municipal council in the Sikar district of the state of Rajasthan in India. It is the administrative headquarters of the Sikar district.'),
(1256409, 1256409, 'IN', 'Shyamnagar', 'Shyamnagar', 'Shyamnagar', 'shyamnagar', 'West Bengal', null, 22.83333, 88.36667, 441956, false, null, 'Shyamnagar is a locality in Bhatpara of North 24 Parganas district in the Indian state of West Bengal. It is a part of the area covered by Kolkata Metropolitan Development Authority.'),
