(1256922, 1256922, 'IN', 'Secunderabad', 'Secunderabad', 'Secunderabad', 'secunderabad', 'Telangana', null, 17.50427, 78.54263, 204182, false, null, 'Secunderabad, formerly Ulwul, is a twin city of Hyderabad and one of the six zones of the Greater Hyderabad Municipal Corporation in the Indian state of Telangana.'),
(1256949, 1256949, 'IN', 'Sawai Madhopur', 'Sawai Madhopur', 'Sawai Madhopur', 'sawai madhopur', 'Rajasthan', null, 26.02301, 76.34408, 121106, false, null, 'Sawai Madhopur is a city in the south-eastern part of the Indian state of Rajasthan. It serves as the administrative headquarter of the Sawai Madhopur district, and forms a part of the Bharatpur division.'),
(1257022, 1257022, 'IN', 'Satna', 'Satna', 'Satna', 'satna', 'Madhya Pradesh', null, 24.57726, 80.82719, 282977, false, null, 'Satna is a city in the Indian state of Madhya Pradesh. It serves as the headquarters of Satna district.'),
