(1257804, 1257804, 'IN', 'Saharsa', 'Saharsa', 'Saharsa', 'saharsa', 'Bihar', null, 25.87498, 86.59611, 156540, false, 'Saharsa, Hindistan''ın Bihar eyaletinde yer alan ve Saharsa ilçesinde yer alan bir şehirdir. Şehrin toplam nüfusu 155.175''tir.', 'Saharsa is a city and municipal corporation in the Saharsa District in the eastern part of the state of Bihar, India.'),
(1257806, 1257806, 'IN', 'Saharanpur', 'Saharanpur', 'Saharanpur', 'saharanpur', 'Uttar Pradesh', null, 29.9679, 77.54522, 484873, false, 'Saharanpur, Hindistan''ın Madhya Pradesh eyaletinde yer alan ve saharanpur ilçesinde yer alan bir şehirdir. Şehrin toplam nüfusu 703.345''tir.', 'Saharanpur is a city and a municipal corporation in Uttar Pradesh, India. It is also the administrative headquarters of Saharanpur district.'),
(1257845, 1257845, 'IN', 'Sagar', 'Sagar', 'Saugor', 'sagar|saugor', 'Madhya Pradesh', null, 23.83877, 78.73874, 274556, false, null, 'Sagar, formerly Saugor, is a city, municipal corporation and administrative headquarter in Sagar district of the state of Madhya Pradesh in central India.'),
