(1258178, 1258178, 'IN', 'Rewari', 'Rewari', 'Rewari', 'rewari', 'Haryana', null, 28.199, 76.6183, 143021, false, null, 'Rewari is a city and a municipal council in Rewari district in the Indian state of Haryana. It is the district headquarters of Rewari district.'),
(1258182, 1258182, 'IN', 'Rewa', 'Rewa', 'Rewa', 'rewa', 'Madhya Pradesh', null, 24.53256, 81.29234, 235654, false, null, 'Rewa is a city in the north-eastern part of Madhya Pradesh state in India. It is the administrative center of Rewa District and Rewa Division.'),
(1258315, 1258315, 'IN', 'Rourkela', 'Rourkela', 'Rourkela', 'rourkela', 'Odisha', null, 22.22496, 84.86414, 273317, false, null, 'Rourkela officially Raurkela is a planned city located in the northern district Sundargarh of Odisha, India. It is a Tier-2 city and the third-largest city in Odisha after Bhubaneswar and Cuttack.'),
