(1263797, 1263797, 'IN', 'Mangalagiri', 'Mangalagiri', 'Mangalagiri', 'mangalagiri', 'Andhra Pradesh', null, 16.43083, 80.56815, 107197, false, null, 'Neighborhood of Mangalagiri-Tadepalle city in Guntur district, Andhra Pradesh, India'),
(1263814, 1263814, 'IN', 'Mandya', 'Mandya', 'Mandya', 'mandya', 'Karnataka', null, 12.5223, 76.89746, 137358, false, null, 'Mandya is a city, also taluka in the state of Karnataka. It is the headquarters of Mandya district.'),
