(1764027, 1764027, 'MY', 'Kampung Sungai Glugur', 'Kampung Sungai Glugur', 'Kampung Sungai Glugur', 'kampung sungai glugur', 'Penang', null, 5.36966, 100.31353, 145600, false, null, null),
(1764160, 1764160, 'MY', 'Kampung Sungai Ara', 'Kampung Sungai Ara', 'Kampung Sungai Ara', 'kampung sungai ara', 'Penang', null, 5.32699, 100.27348, 140849, false, null, 'Human settlement in Malaysia'),
