values
(2892518, 2892518, 'DE', 'Kassel', 'Kassel', 'Kassel', 'kassel', 'Hesse', null, 51.31667, 9.5, 197230, false, 'Kassel, Almanya''nın Hessen eyaletine bağlı bir şehir.', 'Kassel is a city on the Fulda River in northern Hesse, in central Germany. It is the administrative seat of the Regierungsbezirk Kassel and the district of the same name, and had 201,048 inhabitants in December 2020.'),
(2892794, 2892794, 'DE', 'Karlsruhe', 'Karlsruhe', 'Karlsruhe', 'karlsruhe', 'Baden-Wurttemberg', null, 49.00937, 8.40444, 283799, false, 'Karlsruhe, Almanya''nın güneybatısında, Baden-Württemberg eyaletine bağlı, Fransız-Alman sınırındaki şehir.', 'Karlsruhe is the third-largest city of the German state of Baden-Württemberg, after its capital Stuttgart and Mannheim, and the 22nd-largest city in the nation, with 308,436 inhabitants.'),
(2895044, 2895044, 'DE', 'Jena', 'Jena', 'Jena', 'jena', 'Thuringia', null, 50.92878, 11.5899, 104712, false, null, null),
