(3617708, 3617708, 'NI', 'Matagalpa', 'Matagalpa', 'Matagalpa', 'matagalpa', 'Matagalpa Department', null, 12.92795, -85.91906, 109089, false, 'Nikaragua''da Matagalpa belediyesinin ve departmanının idari merkezi olan şehir', 'Matagalpa is a city in Nicaragua which is the capital of the department of Matagalpa. The city has a population of 112,697, while the population of the department is 606,643.'),
(3617723, 3617723, 'NI', 'Masaya', 'Masaya', 'Masaya', 'masaya', 'Masaya Department', null, 11.97316, -86.09587, 130113, false, 'Nikaragua''nın Masaya departmanında kentsel yerleşim ve belediye merkezi', 'Masaya is the capital city of Masaya Department in Nicaragua. It is situated approximately 14 km west of Granada and 31 km southeast of Managua.'),
(3617763, 3617763, 'NI', 'Managua', 'Managua', 'Managua', 'managua', 'Managua Department', null, 12.13282, -86.2504, 973087, true, 'Nikaragua''daki Managua belediyesinin kentsel alanı.', 'Capital city of Nicaragua and seat of Managua Municipality and Managua Department'),
(3618030, 3618030, 'NI', 'León', 'León', 'Leon', 'leon', 'León Department', null, 12.43527, -86.87862, 144538, false, 'Nikaragua''da León belediyesinin idari merkezi ve León departmanının başkenti olan şehir', 'City, municipal seat of León Municipality and capital of León Department, Nicaragua'),
